import pytest
from tools.chapter08_no_source_types_review.test_peer_v2 import package,make,proof
@pytest.mark.parametrize('withdraw,expected',[(False,220),(True,880)])
def test_real_rangedOwnedAura_target_hook_with_sourceNone_and_parent_withdraw(withdraw,expected):
 p=package('arts');quarter=next(b for b in p['buffs'] if b['id']=='buff/peer/hook');quarter['stacking']={'mode':'independent','max_stacks':1};p['buffs'].append({'id':'buff/peer/aura','kind':'buff','aura':{'selector':'selector/peer/aura','buff':'buff/peer/hook'}});p['selectors'].append({'id':'selector/peer/aura','kind':'selector','region':{'type':'radius','radius':1.1},'filters':[{'tag':'player'},{'state':'alive'}],'limit':1});p['entities'].append({'id':'unit/peer/aura','kind':'entity','components':{'spatial':{},'buffs':{'initial':['buff/peer/aura']},'lifecycle':{'policy':'policy/ark_lifecycle'},'abilities':['ability/peer/aura_withdraw']}});p['abilities']=[{'id':'ability/peer/aura_withdraw','kind':'ability','activation':{'mode':'manual','on_start':[{'op':'retire','target':'source','parameters':{'reason':'withdrawn'}}]},'timeline':[]}];p['scenarioDraft']['initialEntities'].append({'definition':'unit/peer/aura','instanceAlias':'aura','position':{'row':0,'col':0}});pr,s=make(p)
 if withdraw:s.submit({'action':'skill','source':'aura','ability':'ability/peer/aura_withdraw'},at=9)
 proof(p,pr,s,'aura_'+str(withdraw),7,20);hits=[e for e in s.session.events if e['type']=='damage.accepted'];assert len(hits)==1 and hits[0]['payload']['source'] is None and hits[0]['payload']['amount']==expected;assert s.ctx.resources.current('target','hp')==8000-expected
